"""QQ-即梦AI出图：按火山引擎即梦AI开放接口（非火山方舟）调用出图。

文档：
- 即梦AI调用说明: https://docs.volcengine.com/docs/AIGCAIzhongtaigongyongwendang/1390583
- 使用API Key调用说明: https://docs.volcengine.com/docs/AIGCAIzhongtaigongyongwendang/api-key-usage-guide

接口域名 ``https://openapi.cv.volces.com``，鉴权 ``Authorization: Bearer <API Key>``：
- 同步任务 CVProcess                 -> /api/common/v3/process
- 同步转异步提交 CVSync2AsyncSubmitTask -> /api/common/v3/submit_task_v2
- 同步转异步查询 CVSync2AsyncGetResult  -> /api/common/v3/get_result_v2

请求体为 JSON：``req_key`` 决定能力（文生图/图生图等），其余参数按能力文档传递；
返回 ``data.binary_data_base64`` 或 ``data.image_urls`` 即结果图。
"""

from __future__ import annotations

import base64
import io
import json
import os
import random
import time
import urllib.error
import urllib.request as urlrequest
from typing import Any

import numpy as np
import torch
from PIL import Image

BASE_URL = "https://openapi.cv.volces.com"
PATH_PROCESS = "/api/common/v3/process"
PATH_SUBMIT = "/api/common/v3/submit_task_v2"
PATH_RESULT = "/api/common/v3/get_result_v2"

ENV_API_KEY = "VOLC_JIMENG_API_KEY"

REQ_KEY_CHOICES = [
    "jimeng_high_aes_general_v21_L",  # 即梦文生图 2.1
    "high_aes_general_v30l_zt2i",     # 即梦文生图 3.0
    "custom",
]

DONE_STATUSES = {"done"}
PENDING_STATUSES = {"in_queue", "generating", "pending", "running", "queued"}


def _api_key(provided: str) -> str:
    key = str(provided or "").strip() or os.environ.get(ENV_API_KEY, "").strip()
    if not key:
        raise ValueError(f"缺少即梦 API Key：请在节点填写，或设置环境变量 {ENV_API_KEY}")
    return key


def _post_json(path: str, payload: dict[str, Any], api_key: str, timeout: float) -> dict[str, Any]:
    request = urlrequest.Request(
        BASE_URL + path,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urlrequest.urlopen(request, timeout=timeout) as response:
            body = response.read()
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", "replace")[:500]
        raise RuntimeError(f"即梦AI HTTP {exc.code}: {detail}") from exc
    try:
        parsed = json.loads(body.decode("utf-8"))
    except ValueError as exc:
        raise RuntimeError(f"即梦AI 返回非 JSON: {body[:200]!r}") from exc
    if not isinstance(parsed, dict):
        raise RuntimeError(f"即梦AI 返回结构异常: {parsed!r}")
    code = parsed.get("code")
    if code not in (10000, 0):
        raise RuntimeError(f"即梦AI 返回 code={code}: {parsed.get('message') or parsed}")
    return parsed


def _image_tensor(data: bytes) -> torch.Tensor:
    image = Image.open(io.BytesIO(data)).convert("RGB")
    array = np.asarray(image, dtype=np.float32) / 255.0
    return torch.from_numpy(array).unsqueeze(0)


def _frames_to_base64(image: torch.Tensor) -> list[str]:
    frames = []
    tensor = image.detach().cpu()
    if tensor.ndim == 3:
        tensor = tensor.unsqueeze(0)
    for index in range(tensor.shape[0]):
        array = (tensor[index].clamp(0, 1).numpy() * 255).round().astype("uint8")
        buffer = io.BytesIO()
        Image.fromarray(array, mode="RGB").save(buffer, format="PNG")
        frames.append(base64.b64encode(buffer.getvalue()).decode("ascii"))
    return frames


def _collect_images(data: dict[str, Any], timeout: float) -> list[bytes]:
    payloads: list[bytes] = []
    for item in data.get("binary_data_base64") or []:
        payloads.append(base64.b64decode(item))
    urls = data.get("image_urls") or []
    for url in urls:
        with urlrequest.urlopen(str(url), timeout=timeout) as response:
            payloads.append(response.read())
    if not payloads:
        raise RuntimeError(f"即梦AI 返回中没有图片数据: {json.dumps(data, ensure_ascii=False)[:400]}")
    return payloads


class QQJimengImage:
    """即梦AI 文生图/图生图（API Key 直连，非火山方舟）。"""

    CATEGORY = "QQ/图像生成"
    FUNCTION = "run"
    RETURN_TYPES = ("IMAGE",)
    RETURN_NAMES = ("图像",)
    DESCRIPTION = (
        "火山引擎即梦AI开放接口出图（非火山方舟）。使用 API Key 以 Bearer 方式鉴权，"
        "req_key 选择能力（文生图2.1/3.0 或自定义）；接了参考图时按图生图/参考图方式传 base64。"
        "默认走同步转异步：提交后轮询 get_result_v2 直到 done；也可切同步 CVProcess 一次返回。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "api_key": (
                    "STRING",
                    {"default": "", "multiline": False, "tooltip": f"火山引擎 API Key；留空时读环境变量 {ENV_API_KEY}"},
                ),
                "req_key": (
                    REQ_KEY_CHOICES,
                    {"default": REQ_KEY_CHOICES[0], "tooltip": "即梦能力 req_key；custom 时使用下面的自定义输入"},
                ),
                "custom_req_key": (
                    "STRING",
                    {"default": "", "multiline": False, "tooltip": "req_key 选 custom 时生效，填接口文档中的 req_key"},
                ),
                "prompt": ("STRING", {"multiline": True, "default": ""}),
                "width": ("INT", {"default": 1024, "min": 512, "max": 2048, "step": 64}),
                "height": ("INT", {"default": 1024, "min": 512, "max": 2048, "step": 64}),
                "seed": ("INT", {"default": -1, "min": -1, "max": 0xFFFFFFFF, "tooltip": "-1 表示每次随机"}),
            },
            "optional": {
                "image": ("IMAGE", {"tooltip": "可选参考图/图生图输入，按顺序转 base64 传入"}),
                "sync": ("BOOLEAN", {"default": False, "tooltip": "True 走 CVProcess 同步接口；False 走提交+轮询"}),
                "timeout_s": ("INT", {"default": 300, "min": 10, "max": 3600}),
                "poll_s": ("FLOAT", {"default": 2.0, "min": 0.2, "max": 60.0, "step": 0.1}),
            },
        }

    def run(self, api_key="", req_key=REQ_KEY_CHOICES[0], custom_req_key="", prompt="",
            width=1024, height=1024, seed=-1, image=None, sync=False, timeout_s=300, poll_s=2.0,
            **_kwargs):
        key = _api_key(api_key)
        ability = str(custom_req_key or "").strip() if req_key == "custom" else str(req_key)
        if not ability:
            raise ValueError("req_key 为 custom 时必须填写 custom_req_key")
        payload: dict[str, Any] = {
            "req_key": ability,
            "prompt": str(prompt or ""),
            "width": int(width),
            "height": int(height),
            "seed": int(seed) if int(seed) >= 0 else random.randint(0, 2**31 - 1),
        }
        if image is not None:
            payload["binary_data_base64"] = _frames_to_base64(image)
        timeout = float(timeout_s)
        if sync:
            parsed = _post_json(PATH_PROCESS, payload, key, timeout)
            data = parsed.get("data") or {}
        else:
            submitted = _post_json(PATH_SUBMIT, payload, key, timeout)
            task_id = str((submitted.get("data") or {}).get("task_id") or "")
            if not task_id:
                raise RuntimeError(f"即梦AI 提交任务未返回 task_id: {submitted}")
            deadline = time.monotonic() + timeout
            data = {}
            while True:
                polled = _post_json(PATH_RESULT, {"req_key": ability, "task_id": task_id}, key, timeout)
                data = polled.get("data") or {}
                status = str(data.get("status") or "")
                if status in DONE_STATUSES:
                    break
                if status and status not in PENDING_STATUSES:
                    raise RuntimeError(f"即梦AI 任务失败 status={status}: {polled.get('message') or polled}")
                if time.monotonic() > deadline:
                    raise RuntimeError(f"即梦AI 任务超时（{timeout_s}s）task_id={task_id}")
                time.sleep(float(poll_s))
        tensors = [_image_tensor(item) for item in _collect_images(data, timeout)]
        return (torch.cat(tensors, dim=0),)


NODE_CLASS_MAPPINGS = {"QQJimengImage": QQJimengImage}
NODE_DISPLAY_NAME_MAPPINGS = {"QQJimengImage": "QQ-即梦AI出图(API Key)"}
